// Writes two generated files:
//  - .cache/app.joined.js: the app's source as one module (the same text Vite builds), so ESLint
//    can check names across all the numbered files at once. Each file is marked with a banner.
//  - src/app/module-globals.d.ts: tells the type checker that the numbered files can use the
//    modules' exports by bare name. Committed; CI fails if it is out of date.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { appSource, exportsOf, MODULES } from './app-source.js';

const dir = fileURLToPath(new URL('../src/app', import.meta.url));
const out = fileURLToPath(new URL('../.cache/app.joined.js', import.meta.url));
const { code, files } = appSource(dir, { banners: true, importPath: f => path.relative(path.dirname(out), f) });
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, code);

const dts =
  '// Generated by build/join.js (npm run lint). Do not edit.\n' +
  MODULES.map((m, i) => `import * as m${i} from './${m}';`).join('\n') +
  '\ndeclare global {\n' +
  MODULES.flatMap((m, i) => exportsOf(path.join(dir, m)).map(n => `  const ${n}: typeof m${i}.${n};`)).join('\n') +
  '\n}\n';
fs.writeFileSync(path.join(dir, 'module-globals.d.ts'), dts);
console.log('joined', files.length, 'numbered files and', MODULES.length, 'modules');
